from typing import Tuple, Dict, Any

def point_type(name: str, fields: Tuple[str, ...], srid_map: Dict[int, str]) -> Any:
    """Dynamically create a Point subclass."""

    class PointMeta(type):
        def __new__(cls, name, bases, dct, **kwargs):
            # Add SRID property to the class
            srid = kwargs.get('srid')
            if srid is not None:
                dct['srid'] = property(lambda self: srid_map.get(srid, 'Unknown SRID'))

            # Add fields as properties
            for field in fields:
                dct[field] = property(lambda self, f=field: getattr(self, f'_{f}'))

            return super().__new__(cls, name, bases, dct)

    class Point(metaclass=PointMeta):
        def __init__(self, *values: Any, srid: int) -> None:
            if len(values) != len(fields):
                raise ValueError(f"Expected {len(fields)} values, got {len(values)}")
            for field, value in zip(fields, values):
                setattr(self, f'_{field}', value)

    return Point
