def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    if not callable(cache) or not callable(key):
        raise ValueError("cache and key must be callable")

    def decorator(func):
        if lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except (KeyError, TypeError):
                    pass  # key not found or invalid key type
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except (ValueError, MemoryError):
                    pass  # value too large or out of memory
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except (KeyError, TypeError):
                    pass  # key not found or invalid key type
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except (ValueError, MemoryError):
                    pass  # value too large or out of memory
                return v
        return _update_wrapper(wrapper, func)
    return decorator

