def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        sentinel = object()
        @lru_cache(maxsize, typed=typed)
        def wrapper(*args, _ttlpolicy=sentinel):
            if _ttlpolicy is sentinel:
                _localcache = {}
                for key, value in cache.cache_info().cache.items():
                    if timer() - value.lru < ttl:
                        _localcache[key] = value
                cache.cache = _localcache
                _ttlpolicy = _localcache
            return func(*args)

        cache = wrapper.cache_clear()
        cache.ttl = ttl
        cache.timer = timer
        cache.maxsize = maxsize
        cache	typed = typed
        setattr(cache, "attr", "value")

        @contextmanager
        def put(*args, **kwargs):
            key = func.cache_info().cache_key(*args)
            yield partial(cache.cache.__setitem__, key)

        wrapper.put = put

        def forget(*args, **kwargs):
            key = func.cache_info().cache_key(*args)
            if key in cache.cache:
                del cache.cache[key]

        wrapper.forget = forget

        def clear():
            cache.cache_clear()

        wrapper.clear = clear

        @wraps(func)
        def memoized_fn(*args, **kwargs):
            result = wrapper(*args, _ttlpolicy=cache)
            return result

        return memoized_fn
    return decorator
