        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else (args, frozenset(kwargs.items()))
            if key not in cache:
                result = func(*args, **kwargs)
                cache[key] = _TtlEntry(result, timer() + ttl)
                if len(cache) > maxsize:
                    cache = MappingProxyType({k: v for k, v in cache.items() if v.expires > timer()})
            elif timer() >= cache[key].expires:
                cache[key] = _TtlEntry(func(*args, **kwargs), timer() + ttl)
            return cache[key].result
        return wraps(func)(wrapper)
    return decorator
