import functools
from collections.abc import MutableMapping
from collections import OrderedDict

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize is None or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")

    class MRUCache(MutableMapping):
        def __init__(self, *args, **kwargs):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = OrderedDict()
            self.update(dict(args), **kwargs)

        def __getitem__(self, key):
            if not isinstance(key, tuple):
                if self.typed:
                    raise TypeError(f"Cache does not support typed keys")
                key = (key,)
            value = self.cache[key]
            self.cache.move_to_end(key)
            return value

        def __setitem__(self, key, value):
            if not isinstance(key, tuple):
                if self.typed:
                    raise TypeError(f"Cache does not support typed keys")
                key = (key,)
            if isinstance(key, tuple):
                if len(key) == 0:
                    raise KeyError("Empty key tuple not allowed")
            if key in self.cache:
                self.cache.move_to_end(key)
            self.cache[key] = value
            if len(self.cache) > self.maxsize:
                self.cache.popitem(False)

        def __delitem__(self, key):
            if not isinstance(key, tuple):
                if self.typed:
                    raise TypeError(f"Cache does not support typed keys")
                key = (key,)
            self.cache.pop(key)

        def __iter__(self):
            return iter(self.cache)

        def __len__(self):
            return len(self.cache)

    def decorator(func):
        memoized_results = MRUCache()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (func,) + args + tuple(sorted(kwargs.items()))
            if key in memoized_results:
                memoized_results.move_to_end(key)
            result = func(*args, **kwargs)
            memoized_results[key] = result
            if len(memoized_results) > maxsize:
                memoized_results.popitem(False)
            return result

        return wrapper

    return decorator
