def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from collections import OrderedDict
    import time

    def decorator(func):
        cache = OrderedDict()
        frequency = {}
        last_updated = {}

        def get_key(*args, **kwargs):
            if typed:
                key = (func, args, tuple(kwargs.items()))
            else:
                key = (func, tuple(sorted(kwargs.items())) + args)
            return key

        def get_or_add_key(key):
            if key not in cache:
                cache[key] = func(*args, **kwargs)
                frequency[key] = 1
                last_updated[key] = time.time()
            return key

        def update_frequency(key):
            frequency[key] += 1
            last_updated[key] = time.time()

        def evict_least_frequent():
            if len(cache) > maxsize:
                lfu_keys = [k for k, v in frequency.items()]
                lfu_keys.sort(key=lambda k: (frequency[k], last_updated[k]))
                lfu_key = lfu_keys[0]
                del cache[lfu_key]
                del frequency[lfu_key]
                del last_updated[lfu_key]

        def wrapper(*args, **kwargs):
            key = get_key(*args, **kwargs)
            key = get_or_add_key(key)
            update_frequency(key)
            evict_least_frequent()
            return cache[key]

        return wrapper

    return decorator

