        key = _lfu_key(key, self.typed)
        if key not in self.cache:
            raise KeyError(key)
        self.frequency[self.usage[key]].remove(key)
        self.usage[key] += 1
        self.frequency[self.usage[key]].append(key)
        return self.cache[key]

    def __setitem__(self, key, value):
        key = _lfu_key(key, self.typed)
        if len(self.cache) >= self.maxsize:
            lfu_keys = self.frequency[min(self.frequency)]
            lfu_key = lfu_keys[0]
            del self.cache[lfu_key]
            del self.usage[lfu_key]
            self.frequency[min(self.frequency)].remove(lfu_key)
        if key in self.cache:
