    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from collections import defaultdict, Counter

    def decorator(func):
        if maxsize <= 0:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        else:
            cache = {}
            frequency = Counter()
            size_heap = []

            def get_key(*args, **kwargs):
                key = args if not typed else (type(a) if isinstance(a, collections.abc.Hashable) else a for a in args), tuple(sorted(kwargs.items()))
                return key

            def update_frequency(key):
                frequency[key] += 1
                heapq.heappush(size_heap, (frequency[key], key))

            def evict():
                while size_heap:
                    freq, key = heapq.heappop(size_heap)
                    if key in frequency:
                        del cache[key]
                        del frequency[key]
                        break

            def wrapper(*args, **kwargs):
                key = get_key(*args, **kwargs)
                if key in cache:
                    update_frequency(key)
                    return cache[key]
                else:
                    result = func(*args, **kwargs)
                    cache[key] = result
                    update_frequency(key)
                    if len(cache) > maxsize:
                        evict()
                    return result

        return wrapper

