class ExceptionFormatter(object):
    @classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        try:
            tb = e.__traceback__
            if tb is None:
                return str(e)

            tb = traceback.extract_tb(tb)
            return cls.format_traceback(tb, max_level, max_path_level)
        except Exception as f:
            return f"Error formatting exception: {f}"

    @classmethod
    def format_traceback(cls, tb, max_level, max_path_level):
        ret = []
        for i, (filename, line_number, function_name, code_line) in enumerate(tb):
            if i >= max_level:
                break
            if filename.find('__builtins__') != -1 or filename.find('site-packages') != -1:
                continue
            ret.append(f"Level {i+1}: {filename}:{line_number} ({function_name})")
            if code_line is not None:
                ret.append(f"    {code_line.strip()}")
        return '\n'.join(ret)

    @classmethod
    def format_exception_info(cls, e):
        return f"{e.__class__.__name__}: {e}"
