def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    minimal = []
    for cls in classes:
        bases = cls.__bases__
        if not bases:
            minimal.append(cls)
        else:
            reduced_bases = minimalBases(bases)
            minimal.append(next((cb for cb in reduced_bases if issubclass(cls, cb))))
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Sort classes by their method resolution order (MRO)
    classes.sort(key=lambda cls: cls.__mro__)

    minimal = []
    for cls in classes:
        # Check if this class is not a subclass of any previously added class
        if not any(issubclass(cls, mcls) for mcls in minimal):
            minimal.append(cls)

    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return ()

    def is_base_of(base, cls):
        return base is cls or is_base_of(base, cls.__base__)

    minimal = []
    for cls in classes:
        if all(not is_base_of(cls, base) for base in minimal):
            minimal.append(cls)

    return tuple(minimal)

