def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    try:
        from ase.parallel import world
        if world.size > 1:
            from ase.parallel import broadcast
            return lambda *args, **kwargs: broadcast(lambda: bw.optimization.c_optimizations_available())(args, kwargs)
        else:
            from bw.optimization import c_optimizations_available
            return c_optimizations_available
    except ImportError:
        raise ImportError("C optimizations are required but not available.")
    except Exception as e:
        raise ImportError(f"An error occurred while checking for C optimizations: {e}")
