    fields = self._fields
    if fields:
        if 'error' not in context:
            context['error'] = {}
        for field in fields:
            if field.startswith('error_'):
                error_name = field[6:]
                if error_name == 'x_low':
                    context['error'].update({
                        'x': {
                            'low': {
                                'index': self._error_indices[error_name]
                            }
                        }
                    })
                elif error_name == 'y_low':
                    context['error'].update({
                        'y': {
                            'low': {
                                'index': self._error_indices[error_name]
                            }
                        }
                    })
                elif error_name == 'z_low':
                    context['error'].update({
                        'z': {
                            'low': {
                                'index': self._error_indices[error_name]
                            }
