                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re
    from django.core.exceptions import ValidationError

    errors = []

    # Regex for valid label keys
    key_regex = re.compile(r'^[a-zA-Z0-9-.]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9-.]+$')

    for key, value in labels.items():
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, str) and not isinstance(v, bytes):
                    errors.append({repr(v): 'expected string or bytes-like object'})
                elif not value_regex.match(v):
                    errors.append({repr(v): "Label value does not match the regex ..."})
        elif not isinstance(value, str) and not isinstance(value, bytes):
            errors.append({repr(value): 'expected string or bytes-like object'})
        elif not value_regex.match(value):
            errors.append({repr(value): "Label value does not match the regex ..."})
        elif not key_regex.match(key):
            errors.append({repr(key): "Label key does not match the regex ..."})
        elif (value_regex.match(key) or key_regex.match(value)) and not isinstance(key, str):
            errors.append({repr(key): 'expected string label key'})

    if errors:
        raise ValidationError({"labels": errors})

