def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    from psycopg2.extensions import adapt

    if self.SQLParams.in_style == 'named':
        placeholders = {f':{name}': adapt(value) for name, value in params.items()}
    elif self.SQLParams.in_style == 'ordinal':
        placeholders = {f'%s': adapt(value) for value in params}
    else:
        raise ValueError(f"Unsupported parameter style: {self.SQLParams.in_style}")

    formatted_sql = sql % placeholders

    if self.SQLParams.in_style == 'named':
        converted_params = {name: value.getquoted() for name, value in placeholders.items()}
    elif self.SQLParams.in_style == 'ordinal':
        converted_params = [value.getquoted() for value in placeholders.values()]

    return formatted_sql, converted_params
