    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        spec_version = self._get_spec_version(inventory)
    else:
        spec_version = self.spec_version

    if self.specifications.get(spec_version):
        self._validate_inventory(inventory, self.specifications[spec_version])
    else:
        raise SchemaNotFoundException(f"Specification version {spec_version} not found")

def _get_spec_version(self, inventory):
    """Extract the specification version from the inventory"""
    type_value = inventory.get('type')
    if isinstance(type_value, dict) and 'version' in type_value:
        return type_value['version']
    return None

def _validate_inventory(self, inventory, spec):
    """Validate the inventory against the given specification"""
    for key, value in inventory.items():
        if key in spec:
            spec_item = spec[key]
            if isinstance(value, list):
                self._validate_list(value, spec_item)
            elif isinstance(value, dict):
                self._validate_dict(value, spec_item)
            else:
