def add_rendition(self, lang, file_path):
        if not os.path.exists(file_path):
            raise ValueError("File does not exist: {}".format(file_path))

        if not isinstance(lang, str) or not lang:
            raise ValueError("Language must be a non-empty string")

        # Split the file name and extension
        base_name, ext = os.path.splitext(file_path)

        # Create the new file name with the language suffix
        new_file_name = "{}-{}.pdf".format(base_name, lang)

        # Check if the new file name already exists
        if os.path.exists(new_file_name):
            raise FileExistsError("Rendition already exists: {}".format(new_file_name))

        # Create the output directory if it does not exist
        output_dir = os.path.dirname(new_file_name)
        if not os.path.exists(output_dir):
            os.makedirs(output_dir)

        # Copy the original file to the new file name
        try:
            shutil.copy(file_path, new_file_name)
            return new_file_name
        except Exception as e:
            raise IOError("Failed to copy file: {}".format(e))

