def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expression in args:
        if isinstance(expression, tuple):
            op, a, b = expression
            if op == 'and':
                if (a[0] == 'or' and a[1][0] == 'not' and a[1][1] == b) or (a[0] == 'and' and a[1] == b):
                    result.append(a[1])
                else:
                    result.append(expression)
            elif op == 'or':
                if (a[0] == 'and' and a[1][0] == 'not' and a[1][1] == b) or (a[0] == 'and' and a[1] == b):
                    result.append(a[1])
                else:
                    result.append(expression)
            else:
                result.append(expression)
        else:
            result.append(expression)
    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def apply_absorption(expr):
        from sympy import And, Or, Not, simplify

        def absorption_rule(expr):
            if expr.is_Or and expr.args[0] == expr.args[1]:
                return expr.args[0]
            return expr

        def negative_absorption_rule(expr):
            if expr.is_And and expr.args[0].is_Not and expr.args[0].args[0] == expr.args[1]:
                return expr.args[2]
            return expr

        return simplify(expr, deep=True, evaluate=False, recursive=True, rules=[absorption_rule, negative_absorption_rule])

    return [apply_absorption(expr) for expr in args]

