        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for exp in args:
        if isinstance(exp, tuple) and len(exp) == 2:
            op, subexp = exp
            if op == 'AND':
                if isinstance(subexp, tuple) and subexp[0] == 'OR':
