        raise ValueError("Root inventory is missing")

    # Dictionary to store content digests different from root inventory
    different_digests = {}

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory')
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory for version {version_dir} not found")

        inventory = self.load_inventory(version_dir)
        if not inventory:
            raise ValueError(f"Inventory for version {version_dir} is missing")

        # Compare inventory with root inventory
        for item, digest in inventory.items():
            if item in root_inventory and root_inventory[item] != digest:
                different_digests[item] = digest

    # Log different content digests
    for item, digest in different_digests.items():
        logging.warning(f"Digest mismatch for {item}: expected {root_inventory.get(item)}, got {digest}")

    return different_digests
