def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    base = len(alphabet)
    if not 0 <= number < base ** len(alphabet):
        raise ValueError("Number is out of the range for the given alphabet")

    result = []
    while number:
        number, remainder = divmod(number, base)
        result.append(alphabet[remainder])

    # Add padding if specified
    if padding is not None and padding > len(result):
        result.extend([alphabet[0]] * (padding - len(result)))

    # Reverse the result to get the most significant digit first
    result.reverse()

    return ''.join(result)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        return '-' + int_to_string(-number, alphabet, padding)
    if padding is not None and number == 0:
        return ''.join(alphabet[0] for _ in range(padding))
    base = len(alphabet)
    if number == 0:
        return alphabet[0]
    result = ""
    while number > 0:
        result = alphabet[number % base] + result
        number //= base
    return result.zfill(padding) if padding is not None else result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    base = len(alphabet)
    if not 2 <= base <= 36:
        raise ValueError("Alphabet size must be between 2 and 36")

    if number == 0:
        if padding is not None:
            return alphabet[0] * padding
        return alphabet[0]

    result = []
    neg = number < 0
    number = abs(number)

    while number:
        result.append(alphabet[number % base])
        number //= base

    if neg:
        result.append('-')

    result.reverse()

    if padding is not None and len(result) < padding:
        result.extend([alphabet[0]] * (padding - len(result)))

    return ''.join(result)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    base = len(alphabet)
    if number == 0:
        return alphabet[0] * (padding or 1)

    result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    if padding and len(result) < padding:
        result.extend([alphabet[0]] * (padding - len(result)))

    return ''.join(reversed(result))

