def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import sys
        platform = 1 if sys.platform.startswith('win') else 0

    if platform == 1:
        pattern = re.compile(r'(\s+)')
    elif platform == 0:
        pattern = re.compile(r'(\s+|["\'])')
    else:
        raise ValueError("Unsupported platform value")

    parts = pattern.split(s)
    return [part.strip() for part in parts if part.strip()]

import os
from pathlib import PosixPath
from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    if not os.path.exists(tmp_path):
        raise FileNotFoundError(f"Temporary path not found: {tmp_path}")

    if not filename:
        filename = os.path.basename(archive_path)

    # Extract the archive to a temporary directory
    extract_dir = os.path.join(tmp_path, filename)
    os.makedirs(extract_dir, exist_ok=True)

    try:
        subprocess.run(
            ['tar', '-xzf', archive_path, '-C', extract_dir],
            check=True
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive: {e}")

    # Return the file repo url
    return os.path.abspath(extract_dir)

