def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma. '''

    try:
        output, status = subprocess.Popen(["git", "status", "--ignored"], stdout=subprocess.PIPE, stderr=subprocess.PIPE).communicate()
        if status != 0:
            raise Exception("Failed to obtain ignored files")

        ignored_files = []
        for line in output.decode('utf-8').split('\n'):
            if any(item in line for item in ignored):
                parts = line.split()
                if len(parts) > 2:
                    ignored_files.append(parts[2])

        ignored_files.sort()
        return ','.join(ignored_files)
    except Exception as e:
        print(f"Error: {e}")
        return ""
