def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        number, unit = frequency.split()
        number = int(number)
        if unit.endswith('s'):
            unit = unit[:-1]
        if unit == 'year':
            return datetime.timedelta(days=number * 365)
        elif unit == 'month':
            return datetime.timedelta(days=number * 30)
        elif unit == 'week':
            return datetime.timedelta(weeks=number)
        elif unit == 'day':
            return datetime.timedelta(days=number)
        elif unit == 'hour':
            return datetime.timedelta(hours=number)
        elif unit == 'minute':
            return datetime.timedelta(minutes=number)
        elif unit == 'second':
            return datetime.timedelta(seconds=number)
        else:
            raise ValueError(f"Invalid time unit: {unit}")
    except (ValueError, AttributeError):
        raise ValueError(f"Invalid frequency string: {frequency}")

import re
from datetime import timedelta

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    pattern = r'(\d+)\s*(day|week|month|year)'
    match = re.match(pattern, frequency, re.IGNORECASE)
    if not match:
        raise ValueError("Invalid frequency format")

    number, unit = match.groups()
    number = int(number)

    if unit.lower() == "day":
        return timedelta(days=number)
    elif unit.lower() == "week":
        return timedelta(weeks=number)
    elif unit.lower() == "month":
        return timedelta(days=number * 30)  # Approximation
    elif unit.lower() == "year":
        return timedelta(days=number * 365)  # Approximation
    else:
        raise ValueError("Invalid unit of time")

