def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not commands or not args:
        raise ValueError("commands and args must be provided")

    for cmd in commands:
        full_command = [cmd] + args
        if cwd:
            full_command += ['--cwd', cwd]
        if hide_stderr:
            full_command += ['--hide-stderr']
        if env:
            full_command += ['--env', env]

        try:
            output = subprocess.check_output(full_command, stderr=subprocess.STDOUT, shell=False)
            if verbose:
                print(output.decode())
        except subprocess.CalledProcessError:
            msg = "couldn't run command:\n" + '\n'.join(full_command)
            raise SystemExit(msg)

    return output.decode() if output else None

