from typing import Set, Optional
from rdflib import Graph, URIRef, Node

def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()

    for s, p, o in graph.triples((None, prop, None)):
        if p == prop:
            roots.discard(s)
            roots.add(o)

    for root in roots.copy():
        for s, p, o in graph.triples((root, prop, None)):
            if p == prop:
                roots.discard(root)
                break

    return roots
