def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.
    """
    from zope.interface import InterfaceClass, Invalid, InterfaceClassImplements, implementer, provider
    if not isinstance(iface, InterfaceClass):
        raise TypeError("iface must be an interface")
    if not callable(candidate):
        raise TypeError("candidate must be a callable")

    if not tentative and not iface.providedBy(candidate):
        raise Invalid("candidate does not provide the interface {}".format(iface))

    methods = set(iface.schema.names(fields='method'))
    attributes = set(iface.schema.names(fields='attribute'))

    missing_methods = methods - candidate.__dict__.keys()
    missing_attributes = attributes - candidate.__dict__.keys()

    if missing_methods or missing_attributes:
        errors = []
        if missing_methods:
            errors.append("Candidate is missing methods: {}".format(missing_methods))
        if missing_attributes:
            errors.append("Candidate is missing attributes: {}".format(missing_attributes))
        raise Invalid('\n'.join(errors))

    incorrect_signatures = []
    for method in methods:
        candidate_method = getattr(candidate, method, None)
        if callable(candidate_method):
            iface_method = iface.schema[method]
            candidate_sig = candidate_method.__code__
            iface_sig = iface_method.__code__
            if (candidate_sig.co_argcount != iface_sig.co_argcount or
                candidate_sig.co_varnames[:candidate_sig.co_argcount] != iface_sig.co_varnames[:iface_sig.co_argcount]):
                incorrect_signatures.append((method, iface_method.__annotations__))
        else:
            incorrect_signatures.append((method, None))

    if incorrect_signatures:
        if len(incorrect_signatures) == 1:
            method, annotation = incorrect_signatures[0]
            raise Invalid("Candidate's method '{}' does not have the correct signature: {}".format(method, annotation))
        else:
            errors = ["Candidate's methods do not have the correct signatures:"] + [
                "{}: {}".format(method, annotation) for method, annotation in incorrect_signatures
            ]
            raise Invalid('\n'.join(errors))

    return True
