def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not hasattr(candidate, "__bases__"):
        return False
    for base in candidate.__bases__:
        if base is iface:
            return True
        if verifyClass(iface, base, tentative=True):
            return True
    if tentative:
        for meth in iface.__dict__:
            if not meth.startswith("__"):
                if not hasattr(candidate, meth):
                    return False
        return True
    return False
