def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._freq or not self._data:
        raise KeyError('cache is empty')

    min_freq = min(self._freq.values())
    key_to_remove = None
    for k, v in self._freq.items():
        if v == min_freq and k in self._data:
            key_to_remove = k
            break

    if key_to_remove is not None:
        value = self._data.pop(key_to_remove)
        del self._freq[key_to_remove]
        for item in self._data.values():
            item[1] -= 1
        return (key_to_remove, value[0])
    else:
        raise KeyError('cache is empty')
