    try:
        host = handle.split("@")[1]
    except (AttributeError, ValueError):
        return None
    document = fetch_document(host=host, path=f"/.well-known/webfinger?resource=acct:{parse.quote(handle)}")
    if document:
        return document
    hostmeta = fetch_document(host=host, path="/.well-known/host-meta", method="GET")
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels=["lrdd"]).template.replace("{uri}", parse.quote(handle))
    document = fetch_document(url, method="GET")
    return document

