                        current_dict[key] = value
        except FileNotFoundError:
            print(f"Warning: Include file '{include_path}' not found.")
        except json.JSONDecodeError:
            print(f"Warning: Error decoding JSON in include file '{include_path}'.")

    if 'include' in parser_dict:
        include_paths = parser_dict.pop('include')
        if isinstance(include_paths, str):
            include_paths = [include_paths]
        for path in include_paths:
            resolve_include(path, parser_dict)
