def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched_args = []
    for option in options_spec:
        if 'required_when' in option:
            condition = option['required_when']
            if self._matches_condition(condition, args):
                matched_args.append(option['name'])
    return matched_args

def _matches_condition(self, condition, args):
    for key, value in condition.items():
        if key not in args or args[key] != value:
            return False
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """

        matched_args = []
        for option in options_spec:
            if 'required_when' in option:
                condition_values = option['required_when']
                for key, value in condition_values.items():
                    if key in args and args[key] == value:
                        matched_args.append(option['dest'])
                        break
        return list(set(matched_args))

