    :param extra_vars: List of extra-vars
    """

    if not extra_vars:
        return vars_dict

    if not isinstance(extra_vars, list):
        raise ValueError("extra_vars must be a list")

    for var in extra_vars:
        if not isinstance(var, dict):
            raise ValueError("Each item in extra_vars must be a dictionary")

        for key, value in var.items():
            if key in vars_dict:
                if isinstance(vars_dict[key], dict) and isinstance(value, dict):
                    vars_dict[key].update(value)
                else:
                    vars_dict[key] = value
            else:
                vars_dict[key] = value

    return vars_dict
