def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    flatten_dict = {}

    def flatten(d, parent_key='', sep='_'):
        for k, v in d.items():
            new_key = parent_key + sep + k if parent_key else k
            if isinstance(v, dict):
                flatten(v, new_key, sep=sep)
            else:
                flatten_dict[new_key] = v

    spec_file = os.path.join(plugin_dir, 'spec.json')
    if os.path.exists(spec_file):
        try:
            with open(spec_file, 'r') as file:
                spec_dict = json.load(file)
                flatten(spec_dict)
        except Exception as e:
            raise ValueError(f"Error reading or parsing spec.json from {plugin_dir}: {e}")

    return flatten_dict
