def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    from collections import defaultdict

    def flatten_dict(d, parent_key='', sep='_'):
        items = defaultdict(dict)
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(flatten_dict(v, new_key, sep=sep).items())
            else:
                items[new_key] = v
        return dict(items)

    try:
        spec_file_path = os.path.join(plugin_dir, 'spec.json')
        with open(spec_file_path, 'r') as file:
            plugin_spec = json.load(file)
        return flatten_dict(plugin_spec)
    except FileNotFoundError:
        print(f"Spec file not found at {spec_file_path}")
        return {}
    except json.JSONDecodeError:
        print(f"Error decoding JSON from {spec_file_path}")
        return {}
